def f(n):
    if n == 2:
        return 5
    elif n == 8:
        return 65
    # 10 -> 101, 12 -> 145
    # Pattern: f(n) = n^2 + 1 for n=10 (100+1=101), n=12 (144+1=145)
    # But 2^2+1=5 matches, 8^2+1=65 matches.
    # So the rule is simply n^2 + 1.
    return n * n + 1
